from collections import defaultdict

attempts = defaultdict(int)
LIMIT = 5

def allow_login(account):
    if attempts[account] >= LIMIT:
        return False
    attempts[account] += 1
    return True

for _ in range(7):
    print(allow_login('demo-user'))

def delay_seconds(failures):
    return min(2 ** max(0, failures - 1), 300)

for failures in range(1, 9):
    print(failures, delay_seconds(failures))

